        // Bound inputs to avoid unrealistic values
        vm.assume(initialDeposit >= 1 ether && initialDeposit <= 10000 ether);
        vm.assume(collectAmount >= 1 && collectAmount <= initialDeposit);

        // Ensure caller has enough ETH to deposit
        vm.deal(caller, initialDeposit);

        // Fund the contract with the deposit
        vm.prank(caller);
        c.Deposit{value: initialDeposit}();

        // Record contract balance before Collect
        uint256 balanceBefore = address(c).balance;

        // Set MinSum to allow the collect
