import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 deposit, uint256 collectAm) public {
        // Bound inputs to reasonable ranges
        deposit = bound(deposit, 1, 100 ether);
        collectAm = bound(collectAm, 1, deposit);

        // Ensure sender is not the zero address
        vm.assume(sender != address(0));

        // Setup: initialize and deposit
        c.Initialized();
        vm.deal(sender, deposit);
        vm.prank(sender);
        c.Deposit{value: deposit}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(sender);

        // Attempt Collect
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, collectAm));

        // Only test the success case
        if (success) {
            uint256 balanceAfter = c.balances(sender);
            assertTrue(balanceAfter == balanceBefore - collectAm, "After Collect, balance should be reduced by collectAm");
        }
    }
}

