contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(sender != address(0));
        vm.assume(collectAmount > 0);

        // Initialize contract so Collect can be called
        c.SetMinSum(0);  // Set MinSum to 0 so any deposit qualifies
        c.Initialized();

        // Deposit some ether
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.Deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;

