pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address user, uint256 deposit, uint256 minSum, uint256 am) public {
        // Bound inputs to reasonable values
        vm.assume(user != address(0));
        vm.assume(deposit >= 1 ether && deposit <= 5000 ether);
        vm.assume(minSum >= 0.5 ether && minSum <= 10 ether);
        vm.assume(am >= 0.5 ether && am <= deposit);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.Initialized();

        // Deposit to user
        vm.deal(user, deposit);
        vm.prank(user);
        c.Deposit{value: deposit}();

        // Ensure user's balance meets MinSum and >= am
        vm.assume(c.balances(user) >= minSum);

        // Record user's ether balance before Collect
        uint256 userBalanceBefore = user.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Call Collect
        bool reverted;
        vm.prank(user);
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If not reverted, the user's balance should increase by exactly _am
        if (!reverted) {
            uint256 userBalanceAfter = user.balance;
            assertTrue(userBalanceAfter == userBalanceBefore + am, "User should receive exactly _am");
        }
    }
}
